questions.solution:
import numpy as np


class Activation_LeakyReLU:
    """f(z) = z for z > 0 and slope * z otherwise."""

    def __init__(self, slope=0.01):
        self.slope = slope

    def forward(self, inputs):
        self.inputs = inputs
        self.output = np.where(inputs > 0, inputs, self.slope * inputs)

    def backward(self, dvalues):
        # f'(z) is 1 where the input was positive and self.slope elsewhere
        self.dinputs = dvalues * np.where(self.inputs > 0, 1.0, self.slope)

