questions.solution:
import numpy as np


class Activation_Sigmoid:

    def forward(self, inputs):
        self.inputs = inputs
        self.output = 1 / (1 + np.exp(-inputs))

    def backward(self, dvalues):
        # f'(z) = sigma(z) * (1 - sigma(z)), read from the cached output
        self.dinputs = dvalues * self.output * (1 - self.output)
